double getArea(Shape shape) {
    return switch (shape) {
        case Circle c -> Math.PI * c.r() * c.r();
        case Rectangle r -> r.w() * r.h();
    };
}

public record Point(int x, int y) {}
public record Window(Point topLeft, Point bottomRight) {}

void printTopLeftX(Object obj) {
    if (obj instanceof Window(Point(int x, int y), Point br)) {
        System.out.println("Top-Left X: " + x);
    }
}

static String evaluate(Object obj) {
    return switch (obj) {
        case Integer i when i > 0 -> "Positive int: " + i;
        case Integer i when i < 0 -> "Negative int: " + i;
        case Integer i -> "Zero";
        case String s when !s.isBlank() -> "Non-empty string: " + s;
        case null, default -> "Other / Null";
    };
}

Thread.ofVirtual().start(() -> {
